import { createRoot } from 'react-dom/client';
import './index.css';
/**
 * Visible Digital Signature sample
 */
import * as React from 'react';
import { createRef, forwardRef } from 'react';
import { ToolbarComponent, ItemsDirective, ItemDirective } from '@syncfusion/ej2-react-navigations';
import { DatePickerComponent } from '@syncfusion/ej2-react-calendars';
import { isNullOrUndefined, select } from '@syncfusion/ej2-base';
import { NumericTextBoxComponent, TextBoxComponent, UploaderComponent } from '@syncfusion/ej2-react-inputs';
import { DropDownListComponent } from '@syncfusion/ej2-react-dropdowns';
import { ButtonComponent, CheckBoxComponent } from '@syncfusion/ej2-react-buttons';
import { PdfViewerComponent, Inject, Toolbar, Magnification, Navigation, Annotation, LinkAnnotation, BookmarkView, ThumbnailView, Print, TextSelection, TextSearch, FormFields, FormDesigner } from '@syncfusion/ej2-react-pdfviewer';
import { MessageComponent } from '@syncfusion/ej2-react-notifications';
import { SampleBase } from './sample-base';

const ForwardedImageList = forwardRef((props, ref) => {
    const imageListRef = createRef();
    React.useImperativeHandle(ref, () => ({
        addImageUrls: (url) => imageListRef.current?.addImageUrls(url),
        getSelectedImageUrl: () => imageListRef.current?.getSelectedImageUrl() ?? '',
        updateSelectedIndex: (index) => imageListRef.current?.updateSelectedIndex(index),
    }));
    return <ImageListClass ref={imageListRef} {...props}/>;
});
class VisibleDigitalSignature extends SampleBase {
    displayModes = ['Image only', 'With signer details', 'Signer details only'];
    digestAlgorithms = ['SHA1', 'SHA256', 'SHA384', 'SHA512', 'RIPEMD160'];
    defaultSignImage = "data:image/png;base64,";
    msgWarning = "The document has been digitally signed and at least one signature has problem ";
    msgError = "The document has been digitally signed, but it has been modified since it was signed and at least one signature is invalid";
    msgSuccess = "The document has been digitally signed and all the signatures are valid";
    pdfviewerApiPath = {
        saveUrl: 'https://ej2services.syncfusion.com/react/development/api/FileUploader/Save',
        removeUrl: 'https://ej2services.syncfusion.com/react/development/api/FileUploader/Remove'
    };
    tabHeaders = [
        { key: 0, text: 'Create new' },
        { key: 1, text: 'Existing Field' }
    ];
    imageListRef;
    viewer;
    uploaderObj;
    displayModeDropDownObj;
    pdfInputRef;
    selectedTab;
    fileName;
    documentData;
    constructor(props) {
        super(props);
        this.viewer = React.createRef();
        this.uploaderObj = React.createRef();
        this.displayModeDropDownObj = React.createRef();
        this.pdfInputRef = React.createRef();
        this.imageListRef = React.createRef();
        this.selectedTab = 0;
        this.fileName = 'visible-digital-signature';
        this.documentData = '';
        this.state = {
            x: 24,
            y: 12,
            height: 120,
            width: 200,
            signatureType: "CAdES",
            displayMode: this.displayModes[1],
            digestAlgorithm: this.digestAlgorithms[1],
            signatureField: "Signature Field 1",
            showSignatureImages: true,
            successVisible: false,
            errorVisible: false,
            warningVisible: false,
            downloadVisibility: true,
            signDocVisibility: true,
            checkBoxStates: {
                signer: true,
                reason: true,
                location: true,
                date: true
            },
            textBoxValues: {
                signer: "James Carter",
                reason: "I am the Author",
                location: "Austin",
                date: this.formatDate(new Date())
            },
            activeTab: 0
        };
    }
    componentDidMount = () => {
        if (!isNullOrUndefined(this.viewer.current)) {
            this.viewer.current.documentLoad = async (args) => {
                this.setState({
                    signDocVisibility: true
                });
                this.fileName = args.documentName;
                try {
                    if (!(this.documentData != null && this.documentData.length > 0)) {
                        this.documentData = await this.blobToBase64(await this.viewer.current.saveAsBlob());
                    }
                    const postData = {
                        documentData: this.documentData
                    };
                    let options = {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(postData)
                    };
                    const apiUrl = 'https://ej2services.syncfusion.com/react/development/api/pdfviewer/ValidateSignature';
                    fetch(apiUrl, options)
                        .then(response => response.json())
                        .then(body => {
                        if (body.successVisible || body.warningVisible || body.errorVisible) {
                            this.setState({
                                signDocVisibility: false
                            });
                        }
                        if (!body.downloadVisibility) {
                            this.setState({
                                downloadVisibility: false
                            });
                        }
                        if ((body.successVisible)) {
                            setTimeout(() => {
                                this.msgSuccess = body.message;
                                this.setState({
                                    successVisible: true
                                });
                            }, 1000);
                            setTimeout(() => {
                                this.setState({
                                    successVisible: false
                                });
                            }, 5000);
                        }
                        if ((body.warningVisible)) {
                            this.msgWarning = body.message;
                            this.setState({
                                warningVisible: true
                            });
                        }
                        if (body.errorVisible) {
                            this.msgError = body.message;
                            this.setState({
                                errorVisible: true
                            });
                        }
                    });
                }
                catch (error) {
                    console.error('Error reading blob', error.message);
                }
            };
        }
    };
    renderTabHeader = () => (<div>
            <div className='e-pv-visible-sign-header-title'>
                <div className='e-pv-visible-sign-group-title'>Signature Field</div>
            </div>
            <div className="e-pv-visible-sign-tab-header">
                {this.tabHeaders.map((header) => (<div key={header.key} onClick={() => this.setState({ activeTab: header.key })} className={`e-pv-visible-sign-tab-header-item${this.state.activeTab === header.key ? ' active' : ''}`}>
                        <div className='e-pv-visible-sign-tab-header-item-text'>
                            {header.text}
                        </div>
                    </div>))}
            </div>
        </div>);
    blobToBase64 = (blob) => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result);
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });
    };
    formatDate = (inputDate) => {
        const month = String(inputDate.getMonth() + 1).padStart(2, '0');
        const date = String(inputDate.getDate()).padStart(2, '0');
        const year = String(inputDate.getFullYear()).slice(-2);
        return `${month}-${date}-${year}`;
    };
    handleTabSelect = (e) => {
        const index = e.selectingIndex ?? 0;
        this.selectedTab = index;
    };
    onFileSuccess = async (args) => {
        const fileData = args.file.rawFile;
        if (fileData instanceof Blob) {
            const imageBase64 = await this.blobToBase64(fileData);
            this.imageListRef.current?.addImageUrls(imageBase64);
            this.uploaderObj.current.clearAll();
        }
        else {
            console.error('Unexpected file data type:', typeof fileData);
        }
    };
    handleCheckboxChange = (field, checked) => {
        this.setState((prevState) => {
            return {
                checkBoxStates: { ...prevState.checkBoxStates, [field]: checked }
            };
        });
    };
    handleTextFieldChange = (field, value) => {
        if (field == 'date') {
            value = this.formatDate(new Date(value));
        }
        this.setState((prevState) => {
            return {
                textBoxValues: { ...prevState.textBoxValues, [field]: value }
            };
        });
    };
    onFileSelect = async (args) => {
        this.uploaderObj.current.upload(args.filesData);
        args.cancel = true;
    };
    browseOpen = (args) => {
        const browseButton = select('#e-pv-visible-sign-image-uploader .e-file-select-wrap button', document);
        if (!isNullOrUndefined(browseButton)) {
            browseButton.click();
        }
        args.preventDefault();
    };
    handleSignImagesVisibility = (args) => {
        this.setState({
            showSignatureImages: args.checked
        });
        if (args.checked) {
            this.displayModeDropDownObj.current.value = this.displayModes[1];
        }
        else {
            this.displayModeDropDownObj.current.value = this.displayModes[2];
        }
    };
    signDocument = async () => {
        this.viewer.current.saveAsBlob()
            .then((blob) => {
            const fileReader = new FileReader();
            fileReader.readAsDataURL(blob);
            fileReader.onload = (event) => {
                const pdfData = event.target ? event.target.result : '';
                const request = new XMLHttpRequest();
                const jsonObject = this.getRequestBody(pdfData);
                const requestData = JSON.stringify(jsonObject);
                request.open('POST', 'https://ej2services.syncfusion.com/react/development/api/pdfviewer/AddVisibleSignature', true);
                request.setRequestHeader('Content-type', 'application/json charset=UTF-8');
                request.onload = () => {
                    if (request.status === 200) {
                        this.documentData = request.responseText;
                        this.viewer.current.load(request.responseText, null);
                        this.viewer.current.fileName = this.fileName;
                        this.viewer.current.downloadFileName = this.fileName;
                        this.setState({
                            signDocVisibility: false
                        });
                    }
                };
                request.onerror = () => {
                    console.error('Error in server', request.statusText);
                };
                request.send(requestData);
            };
            fileReader.onerror = () => {
                console.error('Error reading blob as base 64', fileReader.error);
            };
        })
            .catch((error) => {
            console.error('Error converting blob', error);
        });
    };
    getRequestBody = (pdfData) => {
        const jsonObject = {
            pdfdata: pdfData,
            signatureType: this.state.signatureType.toUpperCase(),
            displayMode: this.state.displayMode.toUpperCase(),
            digestAlgorithm: this.state.digestAlgorithm.toUpperCase()
        };
        if (this.state.showSignatureImages && this.state.displayMode != this.displayModes[2]) {
            const selectedImageData = this.imageListRef.current?.getSelectedImageUrl();
            jsonObject['imagedata'] = selectedImageData;
        }
        if (this.state.checkBoxStates['signer']) {
            jsonObject['signerName'] = this.state.textBoxValues['signer'];
        }
        if (this.state.checkBoxStates['reason']) {
            jsonObject['reason'] = this.state.textBoxValues['reason'];
        }
        if (this.state.checkBoxStates['location']) {
            jsonObject['location'] = this.state.textBoxValues['location'];
        }
        if (this.state.checkBoxStates['date']) {
            jsonObject['date'] = this.state.textBoxValues['date'];
        }
        if (this.state.activeTab == 0) { // Create new
            jsonObject['isSignatureField'] = false;
            jsonObject['signatureBounds'] = JSON.stringify({
                x: this.state.x,
                y: this.state.y,
                height: this.state.height,
                width: this.state.width
            });
        }
        else { // choose existing
            jsonObject['isSignatureField'] = true;
        }
        return jsonObject;
    };
    toolbarClickHandler = (args) => {
        if (args.item.id === 'visibleSign_download') {
            this.viewer.current.download();
        }
    };
    renderSignatureImageGroup = () => {
        return (<>
                <div className='e-pv-visible-sign-signature-image-group'>
                    <div className="e-pv-visible-sign-signature-image-header">
                        <CheckBoxComponent label="Signature image" checked={this.state.showSignatureImages} change={(args) => this.handleSignImagesVisibility(args)}/>
                    </div>
                    {this.state.showSignatureImages && (<>
                            <div id='e-pv-visible-sign-image-uploader' style={{ display: 'none' }}>
                                <UploaderComponent ref={this.uploaderObj} id="signature-image-uploader" allowedExtensions=".jpg,.jpeg,.png" dropArea=".e-pv-visible-sign-tab-panel" asyncSettings={this.pdfviewerApiPath} success={this.onFileSuccess} showFileList={false} selected={this.onFileSelect} multiple={false}/>
                            </div>
                            <ButtonComponent cssClass='e-outline e-primary' onClick={this.browseOpen} style={{ float: 'right' }}>Add Signature</ButtonComponent>
                        </>)}
                </div>
                {this.state.showSignatureImages &&
                <ForwardedImageList imageUrlsProp={[this.defaultSignImage]} selectedIndexProp={0} ref={this.imageListRef}/>}
            </>);
    };
    renderSignatureDescription = () => {
        return (<div className='e-pv-visible-sign-group'>
                <div className="e-pv-visible-sign-group-title" style={{ marginBottom: '6px' }}><span>Signature Description</span></div>
                <table className='e-pv-visible-sign-inner-table'>
                    <tbody>
                        {['signer', 'reason', 'location', 'date'].map((field) => (<tr key={field}>
                                <td>
                                    <CheckBoxComponent checked={this.state.checkBoxStates[field]} change={(e) => this.handleCheckboxChange(field, e.checked)} label={`Show ${field}`}/>
                                </td>
                                <td>
                                    {field == 'date' ?
                    <DatePickerComponent placeholder={`Enter ${field}`} value={new Date(this.state.textBoxValues[field])} format={'MM-dd-yy'} inputFormats={['dd-MM-yy', 'MM-dd-yy']} enabled={this.state.checkBoxStates[field]} allowEdit={false} max={new Date(new Date().getFullYear(), new Date().getMonth(), new Date().getDate())} showClearButton={false} change={(e) => this.handleTextFieldChange(field, e.value)}/>
                    :
                        <TextBoxComponent placeholder={`Enter ${field}`} value={this.state.textBoxValues[field]} enabled={this.state.checkBoxStates[field]} change={(e) => this.handleTextFieldChange(field, e.value)}/>}
                                </td>
                            </tr>))}

                    </tbody>
                </table>
            </div>);
    };
    renderDropdowns = () => {
        return (<div className='e-pv-visible-sign-group'>
                <table className='e-pv-visible-sign-inner-table'>
                    <tbody>
                        <tr>
                            <td>
                                <div className='e-pv-visible-sign-dropdown-label'>
                                    <span>Display mode</span>
                                </div>
                            </td>
                            <td>
                                <DropDownListComponent ref={this.displayModeDropDownObj} enabled={this.state.showSignatureImages} dataSource={this.displayModes} value={this.state.displayMode} change={(args) => this.setState({ displayMode: args.value })} placeholder="Select display mode"/>
                            </td>
                        </tr>
                        <tr>
                            <td>
                                <div className='e-pv-visible-sign-dropdown-label'>
                                    <span>Signature Type</span>
                                </div>
                            </td>
                            <td>
                                <DropDownListComponent dataSource={['CAdES', 'CMS']} value={this.state.signatureType} change={(args) => this.setState({ signatureType: args.value })} placeholder="Select signature type"/>
                            </td>
                        </tr>
                        <tr>
                            <td>
                                <div className='e-pv-visible-sign-dropdown-label'>
                                    <span>Digest Algorithm</span>
                                </div>
                            </td>
                            <td>
                                <DropDownListComponent dataSource={this.digestAlgorithms} value={this.state.digestAlgorithm} change={(args) => this.setState({ digestAlgorithm: args.value })} placeholder="Select Digest Algorithm"/>
                            </td>
                        </tr>
                    </tbody>
                </table>
            </div>);
    };
    createContent = (index) => (<div className='e-pv-visible-sign-tab'>
            <div className='e-pv-visible-sign-tab-content'>
                {index === 0 ? this.createNewContent() : this.existingFieldContent()}
                <hr />
                {this.renderSignatureImageGroup()}
                <hr />
                {this.renderSignatureDescription()}
                <hr />
                {this.renderDropdowns()}
            </div>
        </div>);
    createNewContent = () => {
        return (<div>
                <div className="e-pv-visible-sign-group">
                    <div className="e-pv-visible-sign-group-title"><span>Position</span></div>
                    <table className='e-pv-visible-sign-position-table'>
                        <tbody>
                            <tr>
                                <td>
                                    <div className='e-pv-visible-sign-text-content'>
                                        <span>X</span>
                                        <div className='e-pv-visible-sign-input-item'>
                                            <NumericTextBoxComponent showSpinButton={false} placeholder="24" format='###.##' min={0} change={(args) => this.setState({ x: args.value })} value={this.state.x}/>
                                        </div>
                                    </div>
                                </td>
                                <td>
                                    <div className='e-pv-visible-sign-text-content'>
                                        <span>Y</span>
                                        <div className='e-pv-visible-sign-input-item'>
                                            <NumericTextBoxComponent showSpinButton={false} placeholder="12" format='###.##' min={0} change={(args) => this.setState({ y: args.value })} value={this.state.y}/>
                                        </div>
                                    </div>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>
                <div className="e-pv-visible-sign-group" style={{ marginTop: '6px' }}>
                    <div className="e-pv-visible-sign-group-title"><span>Size</span></div>
                    <table className='e-pv-visible-sign-size-table'>
                        <tbody>
                            <tr>
                                <td>
                                    <div className='e-pv-visible-sign-text-content'>
                                        <span>Width</span>
                                        <div className='e-pv-visible-sign-input-item'>
                                            <NumericTextBoxComponent placeholder="200" format='###.##' min={0} change={(args) => this.setState({ width: args.value })} value={this.state.width}/>
                                        </div>
                                    </div>
                                </td>
                                <td>
                                    <div className='e-pv-visible-sign-text-content'>
                                        <span>Height</span>
                                        <div className='e-pv-visible-sign-input-item'>
                                            <NumericTextBoxComponent placeholder="120" format='###.##' min={0} change={(args) => this.setState({ height: args.value })} value={this.state.height}/>
                                        </div>
                                    </div>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>);
    };
    existingFieldContent = () => {
        return (<div>
                <div className='e-pv-visible-sign-group'>
                    <table className='e-pv-visible-sign-inner-table'>
                        <tbody>
                            <tr>
                                <td>
                                    <div className='e-pv-visible-sign-dropdown-label'>
                                        <span>Existing Field</span>
                                    </div>
                                </td>
                                <td>
                                    <div className='e-pv-visible-sign-text-content'>
                                        <DropDownListComponent dataSource={['Signature Field 1']} value={this.state.signatureField} placeholder="Select existing field"/>
                                    </div>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>);
